const input = $input.first()?.json ?? {};
const mode = String($env.WHATSAPP_MODE ?? '').trim().toLowerCase();
const pilotMode = String($env.PILOT_MODE ?? '').trim().toLowerCase();
const killSwitch = String($env.REPLY_ONLY_KILL_SWITCH ?? 'disabled').trim().toLowerCase();
const payload = input.payload ?? input;
const authenticated = input.authenticated === true || payload.authenticated === true;
const fromMe = Boolean(payload.fromMe ?? payload.key?.fromMe ?? payload.data?.key?.fromMe);
const eventId = String(payload.event_id ?? payload.key?.id ?? '').trim();
const integrationId = String(payload.integration_id ?? '').trim();
if (!authenticated) throw new Error('webhook no autenticado');
if (mode !== 'reply_only' || pilotMode !== 'reply_only' || killSwitch !== 'enabled') throw new Error('reply_only está bloqueado por configuración');
if (!eventId || !integrationId || fromMe) throw new Error('evento inválido o generado por la propia cuenta');
return [{ json: { event_id: eventId, integration_id: integrationId, instance: String(payload.instance ?? '').trim().toLowerCase(), receiver: String(payload.receiver ?? '').replace(/\D/g, ''), sender: String(payload.sender ?? '').replace(/\D/g, ''), text: String(payload.text ?? '').trim(), mode: 'reply_only', mutation_blocked: true, auth_required: true, authenticated } }];

const item = $input.first().json;
// La resolución real debe ejecutarse con la Credential privada de Supabase QA.
// Nunca aceptar tenant_id del payload. Esta plantilla queda inactiva hasta configurar una única allowlist server-side.
if (!item.integration_id || !item.instance || !item.receiver) throw new Error('identidad incompleta');
return [{ json: { ...item, tenant_resolution: 'server_side_allowlist_required', external_effects: false } }];

const item = $input.first().json;
const supported = item.text.length > 0;
const intent = /reserv|turno/i.test(item.text) ? 'booking_request' : /precio|cu[aá]nto/i.test(item.text) ? 'price' : /horario|disponib/i.test(item.text) ? 'availability' : 'faq';
const reply = intent === 'booking_request' ? 'Puedo ayudarte a consultar horarios disponibles. La confirmación del turno debe realizarse desde la página de reservas.' : supported ? 'Respuesta propuesta de prueba: consultaré la información disponible del negocio.' : 'Por ahora puedo ayudarte mejor si me escribís tu consulta.';
return [{ json: { ...item, intent, confidence: 0.9, proposed_response: reply, ai_mock: true, mutation_blocked: true } }];

const item = $input.first().json;
const reply = String(item.proposed_response ?? '').trim();
if (!reply || reply.length > 1000 || /^\s*[\[{]/.test(reply) || /credential|token|clave|stack trace/i.test(reply)) throw new Error('respuesta reply-only no segura');
return [{ json: { ...item, reply_prepared: true, mutation_blocked: true, external_effects: false, mock_send: true } }];

const item = $input.first().json;
// Adapter mock: no hay llamada a Evolution en QA/offline.
return [{ json: { ...item, mock_adapter: 'no_external_request', reply_sent: false, mutation_blocked: true, reservations_created: 0, clients_modified: 0 } }];
